-- FSSAI (Food): six combined questions split (FD01/FD09, FD02/FD10, FD03/FD11, FD04/FD12, FD05/FD13, FD06/FD14/FD15).
update public.hub_chk_points set q='Is the FSSAI registration / licence valid?', why='Selling food without it: fine up to ₹10 lakh.', law='FSS Act 2006 s.31; Licensing Regulations 2011', evidence='FSSAI licence', updated_at=now() where code='FD01';
update public.hub_chk_points set q='Is the FSSAI number printed on our invoices?', why='Compulsory on every food bill.', law='FSSAI order on invoices; licence conditions', evidence='Invoice sample', updated_at=now() where code='FD02';
update public.hub_chk_points set q='Do we buy food products only from FSSAI-licensed makers?', why='The trader shares liability for unsafe or unlicensed food.', law='FSS Act 2006 s.26, 27', evidence='Purchase list checked against licences', updated_at=now() where code='FD03';
update public.hub_chk_points set q='Do the food packs we sell carry the FSSAI logo and number and the veg / non-veg mark?', why='A seller can be fined for mislabelled food on his shelf.', law='FSS (Labelling & Display) Regulations 2020', evidence='Label check per product', updated_at=now() where code='FD04';
update public.hub_chk_points set q='Are our food products and ads free of disease or cure claims?', why='Health supplements and nutraceuticals have strict claim rules.', law='FSS (Advertising & Claims) Regulations 2018', evidence='Claim review note', updated_at=now() where code='FD05';
update public.hub_chk_points set q='Is food stored clean and pest-free?', why='Schedule 4 hygiene rules apply to traders too.', law='FSS Licensing Regulations, Schedule 4', evidence='Store checklist', updated_at=now() where code='FD06';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FD09','FSSAI (Food)','Is the licence in the right category for our turnover and activity (wholesaler, distributor, retailer)?','A wrong category is a violation even with a valid licence.','FSS Act 2006 s.31; Licensing Regulations 2011','food',array[]::text[],'H','FSSAI licence category check',9109,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FD10','FSSAI (Food)','Is the Food Safety Display Board put up?','Compulsory at every licensed premises.','FSSAI licence conditions','food',array[]::text[],'M','Photo of display board',9110,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FD11','FSSAI (Food)','Do we keep a copy of each maker''s FSSAI licence?','The trader shares liability for unsafe or unlicensed food.','FSS Act 2006 s.26, 27','food',array[]::text[],'M','Supplier licence file',9111,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FD12','FSSAI (Food)','Do the packs carry the best-before date, ingredients and nutrition details?','A seller can be fined for mislabelled food on his shelf.','FSS (Labelling & Display) Regulations 2020','food',array[]::text[],'H','Label check per product',9112,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FD13','FSSAI (Food)','Do we hold approvals for any health supplement we sell?','Health supplements and nutraceuticals have strict claim rules.','Nutraceutical Regulations','food',array[]::text[],'M','Product approvals',9113,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FD14','FSSAI (Food)','Is food stored apart from drugs and chemicals?','Schedule 4 hygiene rules apply to traders too.','FSS Licensing Regulations, Schedule 4','food',array[]::text[],'M','Store photos',9114,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('FD15','FSSAI (Food)','Is expired stock kept separately?','Schedule 4 hygiene rules apply to traders too.','FSS Licensing Regulations, Schedule 4','food',array[]::text[],'M','Expired-stock record',9115,true,null) on conflict (code) do nothing;
